def send_with_retry(
    api_helper,
    method: str,
    endpoint: str,
    params: Dict[str, Any],
    headers: Dict[str, str],
    retry_cfg: Dict[str, Any],
) -> requests.Response:
    """
    Simple retry helper on specific HTTP statuses.
    """
    attempts = 0
    last_exc = None
    while attempts < max(1, retry_cfg.get("max_attempts", 1)):
        try:
            response = api_helper.make_request(
                endpoint=endpoint,
                params=params,
                headers=headers,
                method=method,
            )
            if response.status_code in set(retry_cfg.get("retry_on_status", [])):
                attempts += 1
                if attempts >= retry_cfg["max_attempts"]:
                    return response
                time.sleep(retry_cfg.get("backoff_seconds", 1.0))
                continue
            return response
        except (requests.Timeout, requests.ConnectionError) as e:
            last_exc = e
            attempts += 1
            if attempts >= retry_cfg["max_attempts"]:
                raise
            time.sleep(retry_cfg.get("backoff_seconds", 1.0))
    if last_exc:
        raise last_exc
    raise RuntimeError("send_with_retry exhausted attempts unexpectedly")


