# ------------------------------------------------------------------------------------
# Helper Functions to Build Request Parameters From JSON Test Data
# ------------------------------------------------------------------------------------

def build_params_from_item(
    item: Dict[str, Any],
    api_key: str,
    use_dt: bool = True,
    include_range: bool = True,
    use_unix_range: bool = False,
    include_hour: bool = True,
    include_lang: bool = True,
    include_both_dt_and_unix: bool = False,
    make_invalid_range: bool = False,
    drop_q: bool = False,
    coerce_hour_to_string: bool = False,
) -> Dict[str, Any]:
    """
    Construct request params using only values from the JSON test data item.
    Can derive negative scenarios without hardcoded literals.
    """
    params: Dict[str, Any] = {}

    if not drop_q:
        params["q"] = str(item.get("q", ""))

    # dt / unixdt selection
    if include_both_dt_and_unix:
        # Intentionally include both for a negative test
        params["dt"] = str(item.get("dt"))
        params["unixdt"] = int(item.get("unixdt"))
    else:
        if use_dt:
            params["dt"] = str(item.get("dt"))
        else:
            params["unixdt"] = int(item.get("unixdt"))

    # Range params
    if include_range:
        if make_invalid_range:
            # Use the dt value for end_dt to ensure end_dt is not greater than dt (invalid)
            # Still only using values from the JSON item
            if use_unix_range:
                # Use the same unixdt for unixend_dt to make it invalid/non-increasing
                if "unixdt" in item and item["unixdt"] is not None:
                    params["unixend_dt"] = int(item["unixdt"])
            else:
                params["end_dt"] = str(item.get("dt"))
        else:
            if use_unix_range:
                params["unixend_dt"] = int(item.get("unixend_dt"))
            else:
                params["end_dt"] = str(item.get("end_dt"))

    if include_hour and "hour" in item:
        params["hour"] = item["hour"]
        if coerce_hour_to_string:
            params["hour"] = str(params["hour"])

    if include_lang and "lang" in item:
        params["lang"] = str(item.get("lang"))

    # Authentication via query parameter
    if api_key:
        params["key"] = str(api_key)

    return params


