@pytest.mark.parametrize("scenario_selector", ["by_dt", "by_unixdt"])
def test_history_get_success_200(
    api_client,
    api_helper,
    endpoint: str,
    valid_api_key: str,
    test_data: List[Dict[str, Any]],
    api_spec_validator: SwaggerSchemaValidator,
    request_query_schema_strict: Dict[str, Any],
    response_schema_200: Dict[str, Any],
    retry_settings: Dict[str, Any],
    scenario_selector: str,
):
    """
    Validate happy-path GET /v1/history.json returns 200 and matches the 200 response schema.
    Iterates over all entries in history.json.json.
    """
    if not valid_api_key:
        pytest.skip("Valid API key not provided. Provide authentication.ApiKeyAuth in config.yml or key env var.")

    use_dt = scenario_selector == "by_dt"

    for item in test_data:
        params = build_params_from_item(
            item=item,
            api_key=valid_api_key,
            use_dt=use_dt,
            include_range=True,
            use_unix_range=not use_dt,
            include_hour=True,
            include_lang=True,
        )

        # Validate request parameters prior to sending
        api_spec_validator.validate_with_schema(params, request_query_schema_strict)

        # Send request with retry for transient errors
        response = send_with_retry(
            api_helper=api_helper,
            method="GET",
            endpoint=endpoint,
            params=params,
            headers={},
            retry_cfg=retry_settings,
        )

        assert response.status_code == 200, f"Expected 200, got {response.status_code}: {response.text}"
        # Validate response against 200 schema
        json_body = response.json()
        api_spec_validator.validate_with_schema(json_body, response_schema_200)


